# Birney's division from Emmitsburg: Graham "between 5 and 6 P.M.", Ward "after sunset"; Stannard "at dusk"
for id, t0 in (("graham", "16:30"), ("iii_art", "16:45"), ("ward", "18:30"), ("stannard", "18:10")): enter(id, A(t0), S_EMM, 30)
