mv("wilcox", C("15:35"), C("15:55"), (-850, -720), h=90, state="firing"); mv("perry", C("15:35"), C("15:55"), (-800, -520), h=90, state="firing")
fight("wilcox", C("15:55"), C("16:10"), 150); fight("perry", C("15:55"), C("16:10"), 160)
