enter("farnsworth", C("12:40"), (-1100, -4940), 0); walk("farnsworth", C("12:40"), (-1150, -3650), h=0, kmh=6, state="skirmish")
enter("hrobertson", C("12:50"), (-1100, -4940), 0)
